def gen(rng):
    def fmt(xs):
        return str(len(xs)) + '\n' + '\n'.join(map(str, xs))
    tests = [fmt([0]), fmt([1]), fmt([0, 1, 2, 3, 4, 5, 8, 9, 10]), fmt([10**12]), fmt([10**12 - 1, 999999999999])]
    for _ in range(8):
        k = rng.randint(1, 20)
        tests.append(fmt([rng.randint(0, 3000) for _ in range(k)]))
    for _ in range(4):
        k = rng.randint(1, 12)
        xs = []
        for _ in range(k):
            r = rng.randint(0, 1000)
            xs.append(max(0, r * r + rng.choice([-1, 0, 1])))
        tests.append(fmt(xs))
    tests.append(fmt([rng.randint(0, 10**12) for _ in range(10000)]))
    big = []
    for _ in range(10000):
        r = rng.randint(900000, 10**6)
        big.append(max(0, r * r + rng.choice([-1, 0, 1])))
    tests.append(fmt(big))
    tests.append(fmt([10**12] * 10000))
    return tests

